5:/**
6: * createCache({ load, ttlMs = 1000, now = Date.now }) returns a read-through
7: * cache. load and now must be functions (otherwise TypeError); ttlMs must be a
8: * finite nonnegative Number (otherwise RangeError). now is a side-effect-free,
9: * nondecreasing clock returning finite millisecond Numbers.
10: *
11: * Keys use Map/SameValueZero identity and values may include undefined or null.
12: * get(key) always returns a Promise. Missing keys load independently; concurrent
13: * reads of the same key share one active load. load is invoked once with exactly
14: * one argument, the key, and may return a value, Promise, or thenable, or throw.
15: * No particular invocation timing or returned-Promise identity is required.
16: * A successful value's TTL starts when that flight commits, not when get starts.
17: * Cached/set values expire exactly when now() >= their insertion time + ttlMs.
18: * ttlMs = 0 still deduplicates an unsettled flight but never reuses a settled
19: * value. Expiration is lazy; no background timers are needed.
20: *
21: * invalidate(key) removes its value and detaches its active flight immediately.
22: * Readers after invalidate must start/join a fresh flight, even while an older
23: * one is unresolved. Repeated invalidations are separate barriers, including
24: * when the key has no stored value. clear() does the same for every key.
25: * set(key, value) detaches the active flight and installs the supplied value
26: * immediately with a new TTL. That value wins over all earlier loads, and their
27: * later completion must not restart its TTL. If it expires while an old load is
28: * pending, get starts a new load, not the detached one.
29: *
30: * Mutations do not cancel loads or change the outcomes of their original
31: * readers. An obsolete flight still delivers its own value/rejection to all its
32: * original waiters, but cannot store a value or detach a newer flight. Rejected
33: * loads (including synchronous throws and non-Error reasons) are never cached:
34: * all waiters receive the same rejection reason, and a subsequent get may retry.
35: * load may call invalidate, set, or clear synchronously before returning; the
36: * same barrier rules apply. A load may also read another key or read its own key
37: * without awaiting it; the latter joins its existing flight.
38: *
39: * size counts only unexpired stored values, never active flights; reading size
40: * discards expired values without detaching flights. Cache instances are isolated.
41: * invalidate, set, and clear return undefined. These are the public operations;
42: * helpers in flight.js and clock.js are internal implementation details.
43: */
44:function createCache({ load, ttlMs = 1000, now = Date.now } = {}) {
45:  if (typeof load !== 'function') throw new TypeError('load must be a function');
46:  if (!Number.isFinite(ttlMs) || ttlMs < 0) {
47:    throw new RangeError('ttlMs must be a finite nonnegative Number');
48:  }
49:  if (typeof now !== 'function') throw new TypeError('now must be a function');
50:
51:  const values = new Map();
52:  const flights = createFlights();
53:  const clock = createClock(ttlMs, now);
54:
55:  function get(key) {
56:    if (values.has(key)) {
57:      const entry = values.get(key);
58:      if (!clock.expired(entry.deadline)) return Promise.resolve(entry.value);
59:      values.delete(key);
60:    }
61:    return flights.run(key, () => load(key), value => {
62:      values.set(key, { value, deadline: clock.deadline() });
63:    });
64:  }
65:
66:  return {
67:    get,
68:    invalidate(key) {
69:      values.delete(key);
70:      flights.forget(key);
71:    },
72:    set(key, value) {
73:      flights.forget(key);
74:      values.set(key, { value, deadline: clock.deadline() });
75:    },
76:    clear() {
77:      values.clear();
78:      flights.clear();
79:    },
80:    get size() {
81:      for (const [key, entry] of values) {
82:        if (clock.expired(entry.deadline)) values.delete(key);
83:      }
84:      return values.size;
85:    }
86:  };
87:}
88:
89:module.exports = { createCache };

