'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
const def = () => { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; };

(async () => {
  // Rejection not cached; same reason to all waiters; retry works.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, load() { calls++; if (calls === 1) throw 'boom'; return 'ok'; } });
    const a = c.get('k'), b = c.get('k');
    await assert.rejects(a, r => r === 'boom');
    await assert.rejects(b, r => r === 'boom');
    assert.equal(await c.get('k'), 'ok');
    assert.equal(calls, 2);
  }
  // Detached old flight does not detach newer flight nor overwrite its value.
  {
    const gates = [def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load() { return gates[calls++].promise; } });
    const r1 = c.get('k'); await tick();
    c.invalidate('k');
    const r2 = c.get('k'); await tick();
    gates[0].resolve('old'); assert.equal(await r1, 'old');
    const r3 = c.get('k'); // must join flight 2
    gates[1].resolve('new');
    assert.equal(await r2, 'new'); assert.equal(await r3, 'new');
    assert.equal(calls, 2); assert.equal(await c.get('k'), 'new');
  }
  // Repeated invalidations with no stored value are separate barriers.
  {
    const gates = [def(), def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load() { return gates[calls++].promise; } });
    const r1 = c.get('k'); c.invalidate('k');
    const r2 = c.get('k'); c.invalidate('k');
    const r3 = c.get('k');
    gates[2].resolve('c'); gates[1].resolve('b'); gates[0].resolve('a');
    assert.deepEqual(await Promise.all([r1, r2, r3]), ['a', 'b', 'c']);
    assert.equal(await c.get('k'), 'c');
  }
  // set wins over earlier load; TTL not restarted; expiry starts a fresh load.
  {
    let t = 0; const gate = def(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load() { calls++; return calls === 1 ? gate.promise : 'reload'; } });
    const r1 = c.get('k'); await tick();
    c.set('k', 'manual');
    t = 5; gate.resolve('old'); assert.equal(await r1, 'old');
    assert.equal(await c.get('k'), 'manual');
    t = 10; assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'reload'); assert.equal(calls, 2);
  }
  // Detached rejection does not clear a newer flight.
  {
    const gates = [def(), def()]; let calls = 0;
    const c = createCache({ now: () => 0, load() { return gates[calls++].promise; } });
    const r1 = c.get('k'); await tick(); c.clear();
    const r2 = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(r1, /x/);
    const r3 = c.get('k'); gates[1].resolve('v');
    assert.equal(await r2, 'v'); assert.equal(await r3, 'v'); assert.equal(calls, 2);
  }
  // load invalidates synchronously: its value is not stored; own-key read joins.
  {
    let calls = 0; let inner;
    const c = createCache({ now: () => 0, load(k) { calls++; if (calls === 1) { inner = c.get(k); c.invalidate(k); return 'first'; } return 'second'; } });
    assert.equal(await c.get('k'), 'first'); assert.equal(await inner, 'first');
    assert.equal(await c.get('k'), 'second'); assert.equal(calls, 2);
  }
  // ttl 0: dedups unsettled flight, never reuses settled value.
  {
    let calls = 0;
    const c = createCache({ now: () => 0, ttlMs: 0, load() { calls++; return calls; } });
    const [a, b] = await Promise.all([c.get('k'), c.get('k')]);
    assert.equal(a, 1); assert.equal(b, 1); assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 2);
  }
  console.log('all checks passed');
})().catch(e => { console.error(e); process.exit(1); });
